// Write this code and predict the EXACT output order:
// console.log('A');
// setTimeout(() => console.log('B'), 1000);
// setTimeout(() => console.log('C'), 0);
// console.log('D');
// setTimeout(() => console.log('E'), 500);
// console.log('F');

// Write the code below and add comments explaining the order

// Create a countdown from 3 to 0 using setInterval
// Log each number
// When it reaches 0, log 'Go!' and clearInterval

questions.solution:
let count = 3;

const timerId = setInterval(() => {
  console.log(count);
  count--;
  if (count < 0) {
    console.log('Go!');
    clearInterval(timerId);
  }
}, 1000);

questions.starter:
// Function delayedGreet(name, delay)
// Uses setTimeout to log 'Hello, [name]!' after delay ms

// Call 3 times:
// delayedGreet('Amara', 200)
// delayedGreet('Bayo', 500)
// delayedGreet('Chidi', 100)

questions.solution:
function delayedGreet(name, delay) {
  setTimeout(() => {
    console.log('Hello, ' + name + '!');
  }, delay);
}

delayedGreet('Amara', 200);
delayedGreet('Bayo', 500);
delayedGreet('Chidi', 100);

// Output order: Chidi (100ms), Amara (200ms), Bayo (500ms)

