questions.starter:
// Function repeatAction(message, times, interval)
// setInterval to log message every interval ms
// clearInterval after 'times' repetitions

// Call: repeatAction('Saving...', 3, 500)

questions.solution:
function repeatAction(message, times, interval) {
  let count = 0;
  const id = setInterval(() => {
    count++;
    console.log(message + ' (' + count + '/' + times + ')');
    if (count >= times) {
      clearInterval(id);
      console.log('Complete!');
    }
  }, interval);
}

repeatAction('Saving...', 3, 500);

questions.starter:
// Function simulateAPI(data, delay, callback)
// setTimeout → call callback(data) after delay

// Sequential: fetch user name, then fetch score
// Log both values in the final callback

questions.solution:
function simulateAPI(data, delay, callback) {
  setTimeout(() => {
    callback(data);
  }, delay);
}

simulateAPI('Amara', 500, (name) => {
  console.log('User: ' + name);
  simulateAPI(88, 300, (score) => {
    console.log('Score: ' + score);
    console.log('Result: ' + name + ' scored ' + score);
  });
});

