// Log 'Start'
// setTimeout 'Timeout 1' at 0ms
// setTimeout 'Timeout 2' at 0ms
// Log 'End'

// Add comment explaining the output order

questions.solution:
console.log('Start');

setTimeout(() => console.log('Timeout 1'), 0);
setTimeout(() => console.log('Timeout 2'), 0);

console.log('End');

// Output: Start, End, Timeout 1, Timeout 2
// Both timeouts go to the task queue. The event loop only processes
// the queue after the call stack is empty (after all sync code finishes).
// They run in queue order (FIFO): Timeout 1 was queued first.

questions.starter:
// Function processSteps(steps)
// Execute steps sequentially using nested setTimeout (400ms each)
// After all steps: log 'All steps done!'

// Call with ['Validate', 'Process', 'Save']

questions.solution:
function processSteps(steps) {
  function runStep(index) {
    if (index >= steps.length) {
      console.log('All steps done!');
      return;
    }
    setTimeout(() => {
      console.log('Step: ' + steps[index]);
      runStep(index + 1);
    }, 400);
  }
  runStep(0);
}

processSteps(['Validate', 'Process', 'Save']);

