questions.starter:
// Function fetchSequential(urls, callback)
// Fetch each URL sequentially (200ms per fetch, setTimeout)
// Log 'Fetching: [url]' for each
// After all done, call callback(count)

// Call with 3 URLs, callback logs 'Fetched N URLs'

questions.solution:
function fetchSequential(urls, callback) {
  let index = 0;

  function next() {
    if (index >= urls.length) {
      callback(urls.length);
      return;
    }
    setTimeout(() => {
      console.log('Fetching: ' + urls[index]);
      index++;
      next();
    }, 200);
  }

  next();
}

fetchSequential(['api/users', 'api/posts', 'api/comments'], (count) => {
  console.log('Fetched ' + count + ' URLs');
});
